/* From Uiverse.io by Admin12121 - Tags: cardgift, card template, cardhover , card animation */
.__UIV_SCOPE__ .container {
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
}

.__UIV_SCOPE__ .card {
  position: relative;
  display: flex;
  justify-content: center;
  cursor: pointer;
  width: 22em;
  max-width: 80%;
  padding: 2em 0;
  background: #FFF;
  box-shadow: 0 0 6px 0 rgba(32, 32, 36, 0.12);
  transition: all 0.35s ease;
}

.__UIV_SCOPE__ .card::before, .__UIV_SCOPE__ .card::after {
  content: "";
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  background: orange;
  height: 4px;
}

.__UIV_SCOPE__ .card::before {
  width: 0;
  opacity: 0;
  transition: opacity 0 ease, width 0 ease;
  transition-delay: 0.5s;
}

.__UIV_SCOPE__ .card::after {
  width: 100%;
  background: white;
  transition: width 0.5s ease;
}

.__UIV_SCOPE__ .card .content {
  width: 18em;
  max-width: 80%;
}

.__UIV_SCOPE__ .card .logo {
  margin: 0 0 1em;
  width: 10.625em;
  transition: all 0.35s ease;
}

.__UIV_SCOPE__ .card .h6 {
  color: #999;
  font-weight: 600;
  text-transform: uppercase;
  margin: 0;
  letter-spacing: 2px;
}

.__UIV_SCOPE__ .card .hover_content {
  overflow: hidden;
  max-height: 0;
  transform: translateY(1em);
  transition: all 0.55s ease;
}

.__UIV_SCOPE__ .card .hover_content p {
  margin: 1.5em 0 0;
  color: #6E6E70;
  line-height: 1.4em;
}

.__UIV_SCOPE__ .card:hover {
  width: 24em;
  box-shadow: 0 10px 20px 0 rgba(32, 32, 36, 0.12);
}

.__UIV_SCOPE__ .card:hover::before {
  width: 100%;
  opacity: 1;
  transition: opacity 0.5s ease, width 0.5s ease;
  transition-delay: 0;
}

.__UIV_SCOPE__ .card:hover::after {
  width: 0;
  opacity: 0;
  transition: width 0 ease;
}

.__UIV_SCOPE__ .card:hover .logo {
  margin-bottom: 0.5em;
}

.__UIV_SCOPE__ .card:hover .hover_content {
  max-height: 10em;
  transform: none;
}
